const SPEC_NAMES = { rise: 'TOAD RISE', sweep: 'NIGHT SWEEP', dash: 'SWAMP DASH', orb: 'BOG ORB' };
function kitFromStats(st){
  const p = st.power, s = st.speed, r = st.range;
  return {
    dmgMul: 0.82 + p * 0.10, moveMul: 0.86 + s * 0.07,
    dashPow: 5.4 + s * 0.55 + r * 0.20, dashDmg: Math.round(10 + p * 1.6),
    riseDmg: Math.round(9 + p * 1.5), riseHop: 4.6 + s * 0.35,
    sweepPow: 5.0 + s * 0.55, sweepDmg: Math.round(8 + p * 1.4),
    orbDmg: Math.round(7 + r * 1.7), orbPow: 5.4 + r * 0.65, orbLife: 1.8 + r * 0.22,
    ultOrbDmg: 6, ultOrbCount: 3, meterGainMul: 0.95 + s * 0.03,
  };
}


/* Arena-2 overrides: the test is ONE fight, no ladder. */
const FA2_OVR = {
en:{intro:"Two gothic frog champions clash in the ruined colosseum — best of 3 rounds. This is the design test: pick one of the 10 Amphibians champions, and the arena frog IS that character in full 3D armor. Chain jabs, hooks and slide kicks, fire directional specials, and at a full meter unleash the ULTIMATE.",
howtoBody:"Move with the floating joystick (or A/D and ◀ ▶). W jumps, S crouches, hold away or Shift to block. J = jab, K = hook, L = slide kick. U + direction fires a special (25 meter): ↑ launcher · ↓ sweep · → dash · ← orb. At a full 100 meter, U fires the ULTIMATE. Win 2 rounds to take the fight.",
fight:"FIGHT", pickFighter:"CHOOSE YOUR FIGHTER", cpuTag:"CPU PICK"},
};
for (const L of Object.keys(FA2_OVR)) if (I18N[L]) Object.assign(I18N[L], FA2_OVR[L]);
let curLang = localStorage.getItem('farena2_lang') || 'en';
if (!I18N[curLang]) curLang = 'en';
function t(k){ return (I18N[curLang] && I18N[curLang][k]) || I18N.en[k] || k; }
function tf(k, a, b){ return t(k).replace('{a}', a).replace('{b}', b); }
function applyI18n(){
  document.documentElement.lang = curLang;
  const set = (id, v) => { const el = $(id); if (el) el.textContent = v; };
  set('intro', t('intro')); set('howtoBody', t('howtoBody'));
  set('fightBtn', t('fight')); set('pickLabel', t('pickFighter'));
  const ls = $('langSel'); if (ls) ls.value = curLang;
}
const langSel = $('langSel');
if (langSel) {
  for (const [code, name] of LANGS) {
    const o = document.createElement('option'); o.value = code; o.textContent = name;
    langSel.appendChild(o);
  }
  langSel.value = curLang;
  langSel.onchange = () => { curLang = langSel.value; localStorage.setItem('farena2_lang', curLang); applyI18n(); if (window.__fa2Hint) window.__fa2Hint(); };
}
applyI18n();
window.FC = {
  t, tf, SPEC_NAMES, kitFromStats,
  perks: { hp: false, timer: false },
  onChange() {},
  ensureManifest: async () => {},
  postScore: async () => false,
  loadBoard() {},
  playerName: () => '',
};
